<?php
session_start(); if(!isset($_SESSION['admCodigo'])){header('Location: login.php');exit;} require_once 'classe/conexao.php'; $obj=new Conexao(); function hl($v):string{return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}
$r=$obj->consultaPreparada('SELECT l.logCodigo,l.admCodigo,l.logDatahora,l.logTabela,l.logOperacao,l.logChave,l.logSql,l.logUrl,l.logIp,a.admNome FROM log l LEFT JOIN adm a ON a.admCodigo=l.admCodigo ORDER BY l.logCodigo DESC LIMIT 500');
?><!DOCTYPE html><html lang="pt-BR"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Logs</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.8/dist/css/bootstrap.min.css" rel="stylesheet"></head><body><?php include 'header.php';?><div class="container-fluid"><div class="row"><aside class="col-2"><?php include 'menu.php';?></aside><main class="col-10"><h1>Logs do sistema</h1><div class="table-responsive"><table class="table table-sm table-hover"><thead><tr><th>Código</th><th>Data/hora</th><th>Administrador</th><th>Tabela</th><th>Operação</th><th>Chave</th><th>SQL</th><th>URL/IP</th></tr></thead><tbody><?php while($l=$r->fetch()):?><tr><td><?php echo (int)$l['logCodigo'];?></td><td><?php echo hl($l['logDatahora']);?></td><td><?php echo hl($l['admNome']??$l['admCodigo']);?></td><td><?php echo hl($l['logTabela']);?></td><td><?php echo hl($l['logOperacao']);?></td><td><?php echo hl($l['logChave']);?></td><td><code><?php echo hl($l['logSql']);?></code></td><td><?php echo hl($l['logUrl']);?><br><?php echo hl($l['logIp']);?></td></tr><?php endwhile;?></tbody></table></div></main></div></div><?php include 'footer.php';?></body></html>
